import{z as s,x as o,o as A,c as d,q as B,j as i,D as a,d as t,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"策略台账体系","description":"","frontmatter":{"title":"策略台账体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-registry.md","filePath":"quant/sl-registry.md","lastUpdated":1791413859000}'),p={name:"quant/sl-registry.md"};function C(D,E,m,u,f,h){const r=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=B('<h1 id="策略台账体系" tabindex="-1">策略台账体系 <a class="header-anchor" href="#策略台账体系" aria-label="Permalink to &quot;策略台账体系&quot;">​</a></h1><div class="epigraph"><p>模型风险的管理从识别与清单开始：一个模型只有先被登记、写明用途并指定责任人，后面的验证与控制才有落点；策略同理。</p><footer>—— 据 Federal Reserve SR 11-7（2011）的治理框架整理</footer></div><p><a href="/quant/rk-reporting-map">上一课</a>把风险体系收在报告上：每个数字有血缘、每个例外有归因，签字把「知情」变成「负责」，并声明风险体系为策略服务——策略自己从生到退怎么管，是下一课程的主题。本课是「策略生命周期治理」的第一课：先把策略台账立起来。后面各课的版本与审批、容量与衰减治理、合规审查、退出与沉淀，都默认台账存在，只对它读写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有台账的团队长什么样：同一个信号被三个人在不同季度重复研发，各自的 \\(N\\) 都从小计起；实盘某个仓位出了问题，从仓位反查不到是哪个版本的哪条判据批准的；停机的策略没人认领，半年后换个名字重新上线。缺口不是缺一个更好的监控——<a href="/quant/live-drift-monitor">监测只读</a>已经解决「听」，缺的是所有治理动作共读共写的<strong>共享状态</strong>：这个策略现在是谁的、在哪个阶段、凭什么进的、谁批的、容量与衰减预算是多少、\\(N\\) 计到几。</p><p>台账因此不是一份文档，而是一台状态机：每个策略一个全局 id，每个 id 在任一时刻恰有一个生命周期阶段。文档会过期、会有两份互相矛盾；状态机不允许——阶段转移只能由预定义事件触发，触发即留痕。</p><p><span class="marginnote">直觉类比：文档像白板上的字，谁都能改、改了不留痕，两块白板还会互相矛盾；状态机像电梯——只沿预定义的楼层移动，每次移动都刷卡留痕。台账要的是电梯不是白板：阶段只能沿转移边走，走一步记一步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>字段取最小必要集：策略 id；当前版本（指向代码提交、配置与数据快照的哈希，不复制内容）；阶段——研究、评审、模拟、实盘、暂停、退役；owner 与批准人指针；准入判据与冻结日期（两轴过零之类的<a href="/quant/econ-vs-stat-sig">准入口径</a>）；试验计数 \\(N\\) 及其累计范围；容量曲线声明；衰减预算带；退出的预写条件。写入规则三条：追加不改写；阶段只能沿转移边移动；每条转移记录触发事件与时间戳。</p><p>谁读谁写同样要钉死：监测进程对台账只读；审批动作写阶段；研究动作写假设与 \\(N\\)。任何在实盘花钱的仓位，都必须能沿「仓位 → 版本 → 判据 → \\(N\\)」的指针链反查回台账；链条断在任意一环，即为违规持仓，处置优先于解释。</p><p><span class="marginnote">术语翻译：哈希指针存的是内容的一枚「指纹」而不是内容本身——代码或数据哪怕改动一个字节，指纹就对不上。台账因此可以很轻，也骗不了人：想伪造「当时用的是哪份代码」，得先伪造指纹。</span></p>',11)),(A(),i(l,null,{default:a(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E7%A0%94%E7%A9%B6%EF%BC%9A%E5%88%A4%E6%8D%AE%E6%9C%AA%E8%BF%87%22%5D%20--%3E%20EV%5B%22%E8%AF%84%E5%AE%A1%EF%BC%9A%E5%88%A4%E6%8D%AE%E8%BF%87%E9%9B%B6%EF%BC%8CN%20%E5%85%A5%E8%B4%A6%22%5D%0A%20%20EV%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%EF%BC%9A%E5%8F%B0%E9%98%B6%E9%AA%8C%E8%AF%81%22%5D%0A%20%20SIM%20--%3E%20LIVE%5B%22%E5%AE%9E%E7%9B%98%EF%BC%9A%E5%AE%B9%E9%87%8F%E4%B8%8E%E8%A1%B0%E5%87%8F%E9%A2%84%E7%AE%97%E7%94%9F%E6%95%88%22%5D%0A%20%20LIVE%20--%3E%20PAUSE%5B%22%E6%9A%82%E5%81%9C%EF%BC%9A%E7%9B%91%E6%B5%8B%E7%A9%BF%E5%B8%A6%22%5D%0A%20%20PAUSE%20--%3E%20RES%0A%20%20LIVE%20--%3E%20RET%5B%22%E9%80%80%E5%BD%B9%EF%BC%9A%E9%A2%84%E7%AE%97%E8%80%97%E5%B0%BD%E6%88%96%E9%80%80%E5%87%BA%E6%9D%A1%E4%BB%B6%E8%A7%A6%E5%8F%91%22%5D%0A%20%20PAUSE%20--%3E%20RET%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"台账起作用的方式，是把治理动作变成幂等操作。停机脚本重复执行只会命中同一个状态；两个团队同时申请上线同一信号，台账在 id 级撞名即可发现。SR 11-7 对模型要求治理清单与控制，同一逻辑对策略成立：清单让「这个策略还该不该在跑」成为任一时刻都能回答的问题，而不取决于谁在场。指针引用（哈希）而不是复制，保证台账轻、且不与代码库和数据快照漂移——漂移的清单比没有清单更危险，因为它看起来可信。",-1)),E[5]||(E[5]=e("p",null,"阶段转移绑定判据而不是绑定人，是台账与项目管理工具的分界。工单系统里状态可以随意拖动；台账里「模拟 → 实盘」的边上挂着判据引用，拖不上去——除非触发事件真的发生。于是「谁批准的」变成一条可审计记录，而不是会议室记忆。",-1)),(A(),i(l,null,{default:a(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20MON%5B%22%E7%9B%91%E6%B5%8B%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%7C%22%E5%8F%AA%E8%AF%BB%22%7C%20LEDGER%5B%22%E7%AD%96%E7%95%A5%E5%8F%B0%E8%B4%A6%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20APR%5B%22%E5%AE%A1%E6%89%B9%E5%8A%A8%E4%BD%9C%22%5D%20--%3E%7C%22%E5%86%99%E9%98%B6%E6%AE%B5%22%7C%20LEDGER%0A%20%20RES%5B%22%E7%A0%94%E7%A9%B6%E5%8A%A8%E4%BD%9C%22%5D%20--%3E%7C%22%E5%86%99%E5%81%87%E8%AE%BE%E4%B8%8E%20N%22%7C%20LEDGER%0A%20%20LEDGER%20--%3E%20CHAIN%5B%22%E6%8C%87%E9%92%88%E9%93%BE%EF%BC%9A%E4%BB%93%E4%BD%8D%E5%88%B0%E7%89%88%E6%9C%AC%E5%88%B0%E5%88%A4%E6%8D%AE%E5%88%B0%20N%22%5D%0A%20%20CHAIN%20--%3E%20BROKEN%7B%22%E9%93%BE%E6%9D%A1%E5%AE%8C%E6%95%B4%3F%22%7D%0A%20%20BROKEN%20--%3E%7C%22%E6%96%AD%E5%9C%A8%E4%BB%BB%E6%84%8F%E4%B8%80%E7%8E%AF%22%7C%20VIO%5B%22%E8%BF%9D%E8%A7%84%E6%8C%81%E4%BB%93%EF%BC%9A%E5%A4%84%E7%BD%AE%E4%BC%98%E5%85%88%E4%BA%8E%E8%A7%A3%E9%87%8A%22%5D%0A%20%20BROKEN%20--%3E%7C%22%E5%AE%8C%E6%95%B4%22%7C%20OK%5B%22%E5%8F%AF%E5%AE%A1%E8%AE%A1%E6%8C%81%E4%BB%93%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">台账里最先腐烂的通常不是阶段，而是容量声明与 \\(N\\)：前者因为扩容走了非正式渠道，后者因为「只是试一下」没入账。字段必须有唯一写入方，否则宁可不设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>台账不替代监测：监测在<a href="/quant/live-drift-monitor">实盘漂移监测</a>里是只读的顺序检验，台账只是它停机时写入的对象。台账也不替代审批记录本身——批准的论证、反对意见与有效期，属于下一课的版本与审批。\\(N\\) 的跨团队累计口径（同一信号不同人各试过几次算几个）牵涉知识管理，留到后面统一处理。数据管线本身的版本化是数据工程课的主题，本课只引用其哈希。</p><p><span class="marginnote">常见误区：初学者容易以为有了台账就有了治理。台账只回答「现在是什么状态」，不回答「该不该转移」——判据在版本与审批课，读数在监测课。台账是共用的记账本，不是决策者本身；把它当决策者，治理会重新退回人治。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>台账是所有治理动作共读共写的状态机，不是文档：每个策略一个 id，任一时刻恰有一个阶段。</li><li>阶段转移只能由预定义事件触发并留痕；判据挂在转移边上，不挂在人身上。</li><li>实盘仓位必须能沿「仓位 → 版本 → 判据 → \\(N\\)」反查回台账，断链即违规。</li><li>监测只读、审批写状态、研究写假设与 \\(N\\)；字段有唯一写入方才允许存在。</li><li>出处：治理清单与控制原则据 Federal Reserve SR 11-7（2011）整理；监测只读与停机工单闭环见<a href="/quant/live-drift-monitor">实盘漂移监测</a>与<a href="/quant/live-monitoring-handoff">实盘监控与研究再触发</a>。</li></ul>',6))])}const _=s(p,[["render",C]]);export{N as __pageData,_ as default};
